import json, sys, os

def Q(q, **kw):
    d = {"q": q}; d.update(kw); return d
def ALL(*c): return {"all": list(c)}
def ANY(*c): return {"any": list(c)}
def NOT(c): return {"not": c}
def R(name): return {"ref": name}
